/// <summary>
/// Data contract class for importing single files into OMGInboundMessageTable
/// </summary>
[DataContract, SysOperationContractProcessing(classStr(OMGUploadSingleMessageUI))]
class OMGUploadSingleMessageContract extends SysOperationDataContractBase implements SysOperationValidatable
{
    private System.IO.Stream    fileStram;
    private str                 fileName;
    OMGBase64Encode             base64Encode;
    OMGCodePage                 codePage;
    OMGMessageTypeId            messageTypeId;
    OMGMessageGUID              messageGUID;
    OMGMessageName              messageName;


}

Method.Source:
/// <summary>
/// Gets or sets class state value
/// </summary>
/// <param name = "_value">A value to be set [optional]</param>
/// <returns>A class state value</returns>
public System.IO.Stream parmFileStream(System.IO.Stream _value = fileStram)
{
    fileStram = _value;
    return fileStram;
}

/// <summary>
/// Gets or sets class state value
/// </summary>
/// <param name = "_value">A value to be set [optional]</param>
/// <returns>A class state value</returns>
public str parmFileName(str _value = fileName)
{
    fileName = _value;
    return fileName;
}

public OMGMessageGUID parmMessageGUID(OMGMessageGUID _messageGUID = messageGUID)
{
    messageGUID = _messageGUID;

    return messageGUID;
}

/// <summary>
/// Retruns list of available file extensions
/// </summary>
/// <returns>List of available file extensions</returns>
/// <remarks>
/// Empty list means 'all files'. Provide available file extensions by dividing them by comma.
/// Example: '.txt,.csv'
/// </remarks>
public str getAvailableFileTypes()
{
    return '';
}

[DataMember, SysOperationDisplayOrder('1')]
public OMGMessageTypeId parmMessageTypeId(OMGMessageTypeId _messageTypeId = messageTypeId)
{
    messageTypeId = _messageTypeId;

    return messageTypeId;
}

[DataMember, SysOperationDisplayOrder('2')]
public OMGCodePage parmCodePage(OMGCodePage _codePage = codePage)
{
    codePage = _codePage;

    return codePage;
}

[DataMember, SysOperationDisplayOrder('3')]
public OMGBase64Encode parmBase64Encode(OMGBase64Encode _base64Encode = base64Encode)
{
    base64Encode = _base64Encode;

    return base64Encode;
}

[DataMember, SysOperationDisplayOrder('4')]
public OMGMessageName parmMesageName(OMGMessageName _messageName = messageName)
{
    messageName = _messageName;

    return messageName;
}

public boolean validate()
{
    boolean     ret = true;
    ;

    if (!this.parmCodePage())
    {
        ret = checkFailed("@OMG:CodePageMissing");
    }

    if (!this.parmMesageName())
    {
        ret = checkFailed("@OMG:MessageNameMissing");
    }

    if (!this.parmMessageTypeId())
    {
        ret = checkFailed("@OMG:MessageTypeMissing");
    }

    return ret;
}
